class Question{final int id,level,prize;final String question,answer;final List<String> options;Question({required this.id,required this.question,required this.options,required this.answer,required this.level,required this.prize});factory Question.fromJson(Map<String,dynamic> j)=>Question(id:j['id'],question:j['question'],options:List<String>.from(j['options']),answer:j['answer'],level:j['level'],prize:j['prize']);}
